// Receives a brief exported from Jocelyn's WHEN Engine (wl_export_webhook).
// n8n puts the POST JSON under $json.body; tests may put it directly on $json.
const hasBody = $json.body && typeof $json.body === 'object' && Object.keys($json.body).length > 0;
const b = hasBody ? $json.body : $json;
const acct = (b.account && typeof b.account === 'object') ? b.account : {};
const cls = (b.classification && typeof b.classification === 'object') ? b.classification : {};
const when = (b.when && typeof b.when === 'object') ? b.when : {};
const trg = (b.trigger && typeof b.trigger === 'object') ? b.trigger : ((b.trigger_event && typeof b.trigger_event === 'object') ? b.trigger_event : {});
const meta = (b.meta && typeof b.meta === 'object') ? b.meta : {};
const company = acct.name || b.company || (typeof b.account === 'string' ? b.account : null) || meta.account || null;
const when_urgency = b.urgency || when.urgency || cls.urgency || acct.urgency || null;
const when_stage = b.stage || when.stage || cls.stage || b.relationship_stage || null;
const trigger_type = trg.type || b.trigger_type || meta.document_type || 'brief_export';
const industry = b.industry || acct.industry || meta.industry || null;
const trigger_notes = trg.summary || trg.description || b.trigger_notes || null;
return [{ json: {
  company,
  source: 'when_engine_export',
  trigger_type,
  when_urgency,
  when_stage,
  industry,
  trigger_notes,
  brief_generated: true,
  raw_payload: JSON.stringify(b)
} }];
